import json
lines = open('ios_crash.ips').readlines()
raw = ''.join(lines[1:])
raw = raw.replace('\"vmregioninfo\"', '\"vmregioninfo_lower\"')
crash = json.loads(raw)

# Look for any additional info
for key in ['crashReporterKey', 'coalitionName', 'parentProc', 'userID', 'modelCode', 'uptime', 'procExitReason', 'trialInfo']:
    if key in crash:
        val = crash[key]
        if isinstance(val, (dict, list)):
            print(f'{key}: {json.dumps(val)[:200]}')
        else:
            print(f'{key}: {val}')

# Check for ktriageinfo or other diagnostic data
for key in sorted(crash.keys()):
    if key not in ['usedImages', 'threads', 'vmSummary', 'asi', 'exception', 'termination', 'lastExceptionBacktrace']:
        val = crash[key]
        if isinstance(val, str) and len(val) > 200:
            print(f'{key}: {val[:200]}...')
        elif isinstance(val, (dict, list)):
            s = json.dumps(val)
            if len(s) > 200:
                print(f'{key}: {s[:200]}...')
            else:
                print(f'{key}: {s}')
        else:
            print(f'{key}: {val}')
"

